'use strict';

/* eslint-disable max-lines */

// MODULES //

var objectKeys = require( '@stdlib/utils/keys' );
var createCell = require( './create_cell.js' );
var render = require( './render_markdown.js' );
var lower = require( './lower_jupyterlite_javascript.js' );
var diagnostic = require( './diagnostic.js' );
var canonical = require( './canonical.js' );


// FUNCTIONS //

/**
* Throws a conversion error carrying the partial notebook.
*
* @private
* @param {Object} state - conversion state
* @param {string} message - message
* @returns {void}
*/
function throwError( state, message ) {
	var err = new Error( message );
	err.notebook = state.notebook;
	throw err;
}

/**
* Returns resolved directive resources for a code node.
*
* @private
* @param {Object} node - code node
* @param {Object} state - conversion state
* @returns {Array} directives
*/
function directives( node, state ) {
	var out = [];
	var i;

	for ( i = 0; i < node.directiveRefs.length; i++ ) {
		out.push( canonical( state.directives[ node.directiveRefs[ i ] ] ) );
		if ( !state.options.includeProvenance ) {
			delete out[ i ].source;
		}
	}
	return out;
}

/**
* Checks whether attached directives can be represented by the v1 adapter.
*
* @private
* @param {Object} node - code node
* @param {Object} state - conversion state
* @returns {(Object|null)} failure
*/
function checkDirectives( node, state ) {
	var directive;
	var allowed;
	var keys;
	var j;
	var i;

	for ( i = 0; i < node.directiveRefs.length; i++ ) {
		directive = state.directives[ node.directiveRefs[ i ] ];
		if ( !directive || directive.parsed === null ) {
			return {
				'code': 'unsupported-directive',
				'message': 'Code has an unresolved or malformed execution directive.'
			};
		}
		if ( directive.family === 'run' ) {
			allowed = {
				'throws': true,
				'timeout': true
			};
			keys = objectKeys( directive.parsed );
			for ( j = 0; j < keys.length; j++ ) {
				if ( !allowed[ keys[ j ] ] ) {
					return {
						'code': 'unsupported-directive',
						'message': 'Run directive contains an execution policy unsupported by the v1 adapter.'
					};
				}
			}
		} else if ( directive.family !== 'eslint' && directive.family !== 'run-disable' ) {
			return {
				'code': 'unsupported-directive',
				'message': 'Code has a directive family unsupported by the v1 adapter.'
			};
		}
	}
	return null;
}

/**
* Normalizes and joins generated Markdown fragments.
*
* @private
* @param {Array} fragments - fragments
* @returns {string} Markdown source
*/
function joinMarkdown( fragments ) {
	var value;
	var out = [];
	var i;

	for ( i = 0; i < fragments.length; i++ ) {
		value = fragments[ i ].replace( /\r\n?/g, '\n' ).replace( /\n+$/g, '' );
		out.push( value );
	}
	value = out.join( '\n\n' );
	return ( value === '' ) ? '' : value+'\n';
}

/**
* Flushes pending Markdown.
*
* @private
* @param {Object} state - conversion state
* @returns {void}
*/
function flush( state ) {
	var pending = state.pending;

	if ( pending.nodes.length === 0 ) {
		return;
	}
	state.notebook.cells.push( createCell('markdown', joinMarkdown( pending.fragments ), pending.nodes, pending.containers, state) );
	state.pending = {
		'containers': [],
		'fragments': [],
		'nodes': []
	};
}

/**
* Appends a rendered Markdown fragment.
*
* @private
* @param {Object} node - semantic node
* @param {Array} containers - container stack
* @param {Object} state - conversion state
* @returns {void}
*/
function appendMarkdown( node, containers, state ) {
	var result = render( node, state.definitions );
	var slice;

	if ( !result.ok ) {
		diagnostic( state, ( state.options.mode === 'strict' ) ? 'error' : 'warning', result.code, result.message, node );
		if ( state.options.mode === 'strict' ) {
			flush( state );
			throwError( state, 'invalid argument. Unable to render semantic content as Markdown.' );
		}
		slice = render.sourceSlice( node );
		result.value = ( slice === null ) ? '[Unsupported semantic content omitted: '+node.id+']\n' : slice;
	}
	if ( state.pending.nodes.length === 0 ) {
		state.pending.containers = containers.slice();
	}
	state.pending.fragments.push( result.value );
	state.pending.nodes.push( node );
}

/**
* Emits one dedicated display-only code cell.
*
* @private
* @param {Object} node - code node
* @param {Array} containers - container stack
* @param {Object} state - conversion state
* @param {string} disposition - disposition
* @param {string} code - diagnostic code
* @returns {void}
*/
function displayCode( node, containers, state, disposition, code ) {
	var result = render( node, state.definitions );
	var extra;

	flush( state );
	extra = {
		'directives': directives( node, state ),
		'disposition': disposition,
		'execution': node.execution
	};
	if ( code ) {
		extra.failure_codes = [ 'semantic-document-to-ipynb/'+code ];
	}
	state.notebook.cells.push( createCell('markdown', joinMarkdown( [ result.value ] ), [ node ], containers, state, extra) );
}

/**
* Handles an enabled execution candidate which cannot become a code cell.
*
* @private
* @param {Object} node - code node
* @param {Array} containers - container stack
* @param {Object} state - conversion state
* @param {Object} failure - failure
* @returns {void}
*/
function unsupportedCode( node, containers, state, failure ) {
	diagnostic( state, ( state.options.unsupportedCode === 'error' ) ? 'error' : 'warning', failure.code, failure.message, node, failure.details );
	if ( state.options.unsupportedCode === 'error' ) {
		flush( state );
		throwError( state, 'invalid argument. Execution candidate is not eligible for the selected JupyterLite target.' );
	}
	displayCode( node, containers, state, 'display-only', failure.code );
}

/**
* Converts a semantic code node.
*
* @private
* @param {Object} node - code node
* @param {Array} containers - container stack
* @param {Object} state - conversion state
* @returns {void}
*/
function code( node, containers, state ) {
	var failure;
	var result;
	var extra;
	var tags = [];

	if ( node.execution.intent !== 'candidate' ) {
		appendMarkdown( node, containers, state );
		return;
	}
	if ( node.execution.disabled ) {
		diagnostic( state, 'info', 'execution-disabled', 'Execution candidate is disabled and was emitted as display-only Markdown.', node );
		displayCode( node, containers, state, 'disabled', 'execution-disabled' );
		return;
	}
	if ( node.language !== state.target.kernelspec.language ) {
		unsupportedCode( node, containers, state, {
			'code': 'language-mismatch',
			'message': 'Execution candidate language does not match the notebook kernel language.',
			'details': {
				'actual': node.language,
				'expected': state.target.kernelspec.language
			}
		});
		return;
	}
	failure = checkDirectives( node, state );
	if ( failure ) {
		unsupportedCode( node, containers, state, failure );
		return;
	}
	result = lower( node.value, state.options, state.target.runtime );
	if ( !result.ok ) {
		unsupportedCode( node, containers, state, result );
		return;
	}
	flush( state );
	extra = {
		'directives': directives( node, state ),
		'disposition': 'executable',
		'execution': node.execution
	};
	if ( result.transforms.length ) {
		extra.pre_transform_source = node.value;
		extra.transforms = result.transforms;
		if ( state.options.includeProvenance ) {
			failure = render.sourceSlice( node );
			if ( failure !== null ) {
				extra.authored_source_slice = failure;
			}
		}
	}
	if ( node.execution.expected === 'throws' ) {
		tags.push( 'raises-exception' );
	}
	state.notebook.cells.push( createCell('code', result.code, [ node ], containers, state, extra, tags) );
}

/**
* Converts one semantic leaf.
*
* @private
* @param {Object} node - semantic node
* @param {Array} containers - container stack
* @param {Object} state - conversion state
* @returns {void}
*/
function leaf( node, containers, state ) {
	if (
		node.type === 'thematicBreak' &&
		state.redundantBreaks[ node.id ]
	) {
		omitBreak( node, state );
		return;
	}
	if ( node.type === 'code' ) {
		code( node, containers, state );
		return;
	}
	if ( node.type === 'raw' && node.format !== 'html' ) {
		flush( state );
		state.notebook.cells.push( createCell('raw', node.value, [ node ], containers, state, {
			'disposition': 'raw',
			'format': node.format
		}) );
		return;
	}
	appendMarkdown( node, containers, state );
}

/**
* Tests whether a semantic section is excluded by conversion policy.
*
* @private
* @param {Object} node - semantic container
* @param {Object} state - conversion state
* @returns {boolean} boolean
*/
function isExcluded( node, state ) {
	return (
		node.type === 'section' &&
		state.options.excludeSectionRoles.indexOf( node.role ) >= 0
	);
}

/**
* Records an intentionally omitted semantic section subtree.
*
* @private
* @param {Object} node - semantic section
* @param {Object} state - conversion state
* @returns {void}
*/
function omitSection( node, state ) {
	state.omissions.push({
		'id': node.id,
		'reason': 'excluded-section-role',
		'role': node.role,
		'semantic_key': node.semanticKey,
		'tree_hash': node.treeHash,
		'type': node.type
	});
}

/**
* Records a thematic break made redundant by section exclusion.
*
* @private
* @param {Object} node - semantic thematic break
* @param {Object} state - conversion state
* @returns {void}
*/
function omitBreak( node, state ) {
	state.omissions.push({
		'id': node.id,
		'payload_hash': node.payloadHash,
		'reason': 'redundant-thematic-break',
		'semantic_hash': node.semanticHash,
		'type': node.type
	});
}

/**
* Returns the complete source offsets for a semantic node.
*
* @private
* @param {Object} node - semantic node
* @returns {(Object|null)} source offsets
*/
function sourceOffsets( node ) {
	var envelope = node.source.envelope;
	var start = null;
	var refs;
	var end;
	var i;

	if (
		envelope &&
		envelope.start &&
		envelope.end &&
		typeof envelope.start.offset === 'number' &&
		typeof envelope.end.offset === 'number'
	) {
		return {
			'end': envelope.end.offset,
			'start': envelope.start.offset
		};
	}
	refs = node.source.refs;
	if ( refs.length === 0 ) {
		return null;
	}
	for ( i = 0; i < refs.length; i++ ) {
		if (
			!refs[ i ].range ||
			typeof refs[ i ].range.start.offset !== 'number' ||
			typeof refs[ i ].range.end.offset !== 'number'
		) {
			return null;
		}
		if ( start === null || refs[ i ].range.start.offset < start ) {
			start = refs[ i ].range.start.offset;
		}
		if ( end === void 0 || refs[ i ].range.end.offset > end ) {
			end = refs[ i ].range.end.offset;
		}
	}
	return {
		'end': end,
		'start': start
	};
}

/**
* Collects retained leaves and section-exclusion markers in semantic flow order.
*
* @private
* @param {Array} children - semantic children
* @param {Object} state - conversion state
* @param {Array} out - output tokens
* @returns {void}
*/
function flowTokens( children, state, out ) {
	var node;
	var i;

	for ( i = 0; i < children.length; i++ ) {
		node = children[ i ];
		if ( isExcluded( node, state ) ) {
			out.push({
				'excluded': true,
				'node': node
			});
		} else if ( node.type === 'section' || node.type === 'topic' ) {
			flowTokens( node.children, state, out );
		} else {
			out.push({
				'excluded': false,
				'node': node
			});
		}
	}
}

/**
* Marks thematic breaks made adjacent by excluded section subtrees.
*
* @private
* @param {Object} doc - semantic document
* @param {Object} state - conversion state
* @returns {void}
*/
function markRedundantBreaks( doc, state ) {
	var redundant = Object.create( null );
	var separated = false;
	var previous = null;
	var offsets;
	var tokens = [];
	var token;
	var i;

	flowTokens( doc.children, state, tokens );
	if ( state.recoverOrder ) {
		for ( i = 0; i < tokens.length; i++ ) {
			offsets = sourceOffsets( tokens[ i ].node );
			if ( offsets === null ) {
				state.redundantBreaks = redundant;
				return;
			}
			tokens[ i ].start = offsets.start;
		}
		tokens.sort( sourceOrder );
	}
	for ( i = 0; i < tokens.length; i++ ) {
		token = tokens[ i ];
		if ( token.excluded ) {
			if ( previous ) {
				separated = true;
			}
			continue;
		}
		if ( token.node.type === 'thematicBreak' ) {
			if ( previous && separated ) {
				redundant[ previous.node.id ] = true;
			}
			previous = token;
			separated = false;
		} else {
			previous = null;
			separated = false;
		}
	}
	state.redundantBreaks = redundant;
}

/**
* Walks semantic children depth first.
*
* @private
* @param {Array} children - semantic children
* @param {Array} containers - container stack
* @param {Object} state - conversion state
* @returns {void}
*/
function walk( children, containers, state ) {
	var node;
	var i;

	for ( i = 0; i < children.length; i++ ) {
		node = children[ i ];
		if ( isExcluded( node, state ) ) {
			flush( state );
			omitSection( node, state );
			continue;
		}
		if ( node.type === 'section' || node.type === 'topic' ) {
			flush( state );
			containers.push( node );
			walk( node.children, containers, state );
			flush( state );
			containers.pop();
		} else {
			leaf( node, containers, state );
		}
	}
}

/**
* Collects leaves and their container lineage for unambiguous order recovery.
*
* @private
* @param {Array} children - semantic children
* @param {Array} containers - container stack
* @param {Array} out - output entries
* @param {Object} state - conversion state
* @returns {boolean} boolean indicating whether every leaf has a complete range
*/
function collect( children, containers, out, state ) {
	var offsets;
	var node;
	var i;

	for ( i = 0; i < children.length; i++ ) {
		node = children[ i ];
		if ( isExcluded( node, state ) ) {
			omitSection( node, state );
			continue;
		}
		if ( node.type === 'section' || node.type === 'topic' ) {
			containers.push( node );
			if ( !collect( node.children, containers, out, state ) ) {
				return false;
			}
			containers.pop();
		} else {
			offsets = sourceOffsets( node );
			if ( offsets === null ) {
				return false;
			}
			out.push({
				'containers': containers.slice(),
				'end': offsets.end,
				'node': node,
				'start': offsets.start
			});
		}
	}
	return true;
}

/**
* Tests whether two container lineages are identical.
*
* @private
* @param {Array} x - first lineage
* @param {Array} y - second lineage
* @returns {boolean} boolean
*/
function sameLineage( x, y ) {
	var i;

	if ( x.length !== y.length ) {
		return false;
	}
	for ( i = 0; i < x.length; i++ ) {
		if ( x[ i ].id !== y[ i ].id ) {
			return false;
		}
	}
	return true;
}

/**
* Compares two recovered semantic leaves by source offset.
*
* @private
* @param {Object} a - first entry
* @param {Object} b - second entry
* @returns {number} comparison result
*/
function sourceOrder( a, b ) {
	return a.start-b.start;
}

/**
* Traverses leaves in recovered source order.
*
* @private
* @param {Object} doc - semantic document
* @param {Object} state - conversion state
* @returns {void}
*/
function recover( doc, state ) {
	var previous = null;
	var entries = [];
	var i;

	if ( !collect( doc.children, [], entries, state ) ) {
		diagnostic( state, 'error', 'ambiguous-source-order', 'Semantic source order cannot be recovered without complete leaf ranges.', null );
		throwError( state, 'invalid argument. Cannot recover semantic source order without complete leaf ranges.' );
	}
	entries.sort( sourceOrder );
	for ( i = 0; i < entries.length; i++ ) {
		if ( i > 0 && entries[ i ].start < entries[ i-1 ].end ) {
			diagnostic( state, 'error', 'ambiguous-source-order', 'Semantic source order cannot be recovered because leaf ranges overlap.', entries[ i ].node );
			throwError( state, 'invalid argument. Cannot recover overlapping semantic leaf ranges.' );
		}
		if ( previous && !sameLineage( previous, entries[ i ].containers ) ) {
			flush( state );
		}
		leaf( entries[ i ].node, entries[ i ].containers, state );
		previous = entries[ i ].containers;
	}
}


// MAIN //

/**
* Traverses semantic flow and appends notebook cells.
*
* @param {Object} doc - semantic document
* @param {Object} state - conversion state
* @returns {void}
*/
function traverse( doc, state ) {
	markRedundantBreaks( doc, state );
	if ( state.recoverOrder ) {
		recover( doc, state );
	} else {
		walk( doc.children, [], state );
	}
	flush( state );
}


// EXPORTS //

module.exports = traverse;
